const $=s=>document.querySelector(s), e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const REF='https://morrisrrrrrrr-svg.github.io/',fmt=n=>n==null?'未知':Number(n).toLocaleString('zh-TW'), routes=[['home','⌂','我的角色'],['training','↗','練功推薦'],['monsters','♧','怪物與掉落'],['items','◇','道具與製作'],['quests','☷','任務手札'],['maps','⌘','地圖圖鑑'],['skills','✦','技能圖鑑'],['plan','✓','我的材料清單'],['favorites','☆','我的收藏'],['exp','◷','經驗計算器'],['guides','▤','攻略指南'],['tools','⚒','其他工具'],['library','▤','活動與資料中心'],['audit','✓','版本審核']];
const localAssets=new Set(await fetch('assets/manifest.json').then(r=>r.ok?r.json():[]).catch(()=>[]));
function savedState(s={}){const profile=normalizeProfile(s.profile);return{profile:validProfile(profile)?profile:{...DEFAULT_PROFILE},selected:Array.isArray(s.selected)?s.selected.map(String):[],completed:Array.isArray(s.completed)?s.completed.map(String):[],favorites:Array.isArray(s.favorites)?s.favorites:[],records:Array.isArray(s.records)?s.records:[],timers:Array.isArray(s.timers)?s.timers:[]}}
function readSave(){try{const s=JSON.parse(localStorage.getItem('kiwi-maple-v1')||'{}'),state=savedState(s);const characters=Array.isArray(s.characters)?s.characters.filter(c=>typeof c.id==='string'&&typeof c.name==='string'&&validProfile(c.profile)).map(c=>({id:c.id,name:c.name.slice(0,40),...savedState(c)})):[];if(!characters.length)characters.push({id:'main',name:'我的'+jobName(state.profile),...state});const current=characters.find(c=>c.id===s.activeCharacter)||characters[0];return{...savedState(current),characters,activeCharacter:current.id}}catch{const state=savedState();return{...state,characters:[{id:'main',name:'我的僧侶',...state}],activeCharacter:'main'}}}
let questStatus='all',auditQuery='',auditStatus='all',auditKind='all',auditPageNumber=1;
let expMode='planner',minLevel='',maxLevel='',region='',weakness='',bossOnly=false,sortOrder='level',guideCategory='',guideQuery='';
let save=readSave(),view='',page=1,query='',filter='',onlyRole=false,healOnly=false,activeTool='combat',generation=0;const cache=new Map(),detailCache=new Map();
function persist(){stashCharacter(save);try{localStorage.setItem('kiwi-maple-v1',JSON.stringify(save));return true}catch{toast('瀏覽器無法保存，請使用匯出備份。');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500)}
async function data(name){if(!cache.has(name))cache.set(name,fetch(`data/${name}.json`).then(r=>{if(!r.ok)throw Error('資料讀取失敗，請重新整理或重建網站。');return r.json()}).catch(err=>{cache.delete(name);throw err}));return cache.get(name)}
async function detail(kind,id){const key=`${kind}-detail/${Math.floor(Number(id)/1000)}`;if(!detailCache.has(key))detailCache.set(key,data(key));return(await detailCache.get(key))[String(id)]}
function image(path,cls=''){if(!path)return '';try{const u=new URL(path,REF);if(u.origin!==new URL(REF).origin)return '';const local=path.split('?')[0].replace(/^\.\//,'');return `<img class="${cls}" src="${e(localAssets.has(local)?local:u.href)}" alt="" loading="lazy" decoding="async">`}catch{return ''}}
const sprite=path=>`<div class="sprite">${path?image(path):'◇'}</div>`;
const tag=(t,g='')=>`<span class="tag ${g}">${e(t)}</span>`;
function heading(title,sub){return `<div class="heading"><div><div class="eyebrow">YOUR MAPLE JOURNAL</div><h1>${e(title)}</h1><p>${e(sub)}</p></div><span class="date">${new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',year:'numeric',month:'long',day:'numeric'}).format(new Date())}</span></div>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${e(x)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(x=>`<td class="wrap">${x??'—'}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">目前沒有資料</td></tr>`}</tbody></table></div>`}
const link=(kind,id,name)=>`<button class="inline-link" data-detail="${e(kind)}" data-id="${e(id)}">${e(name||id)}</button>`;
function chips(rows,kind){return `<div class="chips">${rows.map(i=>`<span class="chip">${kind?link(kind,i.id,i.name):e(i.name||i.id)} ${i.count!=null?'× '+fmt(i.count):''}</span>`).join('')||'<span class="muted">來源未列</span>'}</div>`}
function questCompletion(id,name){const done=save.completed.includes(String(id));return `<label class="quest-completion ${done?'is-complete':''}"><input type="checkbox" data-quest-completed="${e(id)}" aria-label="${e(name)} 已完成" ${done?'checked':''}><span>${done?'已完成':'未完成'}</span></label>`}
function favorite(kind,id){return save.favorites.includes(`${kind}:${id}`)}
function card(kind,r){const fav=favorite(kind,r.id);let badge='',sub='',stats='',note='';
if(kind==='monsters'){badge=`Lv.${r.level??'?'}`;sub=(r.continents||[]).join(' · ');stats=`<div>HP<strong>${fmt(r.stats?.maxHP)}</strong></div><div>EXP<strong>${fmt(r.stats?.exp)}</strong></div><div>類型<strong>${r.stats?.undead?'不死系':r.stats?.boss?'BOSS':'一般'}</strong></div>`;note=r.onlyUnnamedMaps?'僅有未命名地圖，開放狀態待確認':'可查看完整掉落物與出沒地圖';}
if(kind==='items'){badge=r.subcategory||r.category;sub=`ID ${r.id} · ${r.category}`;stats=`<div>需求等級<strong>${fmt(r.equipStats?.reqLevel??0)}</strong></div><div>已知來源<strong>${Object.values(r.sourceCounts||{}).reduce((s,x)=>s+x,0)}</strong></div>`;note=r.hasSource?'查詢怪物掉落、任務、商店與製作關係':'來源尚未收錄，不代表目前可取得';}
if(kind==='maps'){badge=r.regionName||'地區待確認';sub=r.street||`ID ${r.id}`;stats=`<div>生怪點<strong>${fmt(r.monsterSpawnCount)}</strong></div><div>NPC<strong>${fmt(r.npcSpawnCount)}</strong></div><div>傳點<strong>${fmt(r.portalCount)}</strong></div>`;note=r.specialMap?'特殊地圖，請核對開放與進入條件':'查看怪物、NPC 與傳送點';}
if(kind==='skills'){badge=r.advancement||'共通';sub=r.jobName;stats=`<div>等級上限<strong>${r.maxLevel}</strong></div><div>技能 ID<strong>${r.id}</strong></div>`;note='查看逐級數值與職業分類';}
return `<article class="card clickable" data-detail="${kind}" data-id="${e(r.id)}" tabindex="0" role="button" aria-label="查看${e(r.name)}"><div class="card-top">${sprite(r.image)}${tag(badge)}<button class="favorite" data-favorite="${kind}:${e(r.id)}" aria-label="${fav?'取消收藏':'收藏'}${e(r.name)}">${fav?'★':'☆'}</button></div><h3>${e(r.name)}</h3><div class="subtitle">${e(sub)}</div><div class="card-stats">${stats}</div><p class="note">${e(note)}</p></article>`}
function updateHeader(){const p=save.profile;$('#profile-label').textContent=`Lv.${p.level} ${jobName(p)}`;const groups=[['資料庫',['monsters','items','quests','maps','skills']],['計算與攻略',['exp','tools','guides','library','audit']],['個人紀錄',['training','home','plan','favorites']]];$('#nav').innerHTML=groups.map(([title,ids])=>`<div class="nav-group"><p class="nav-label">${title}</p>${ids.map(id=>{const r=routes.find(r=>r[0]===id);return `<a href="#${id}" class="${view===id?'active':''}"><i>${r[1]}</i>${r[2]}${id==='plan'?`<span class="badge">${save.selected.length}</span>`:''}</a>`}).join('')}</div>`).join('');$('#breadcrumb').textContent=routes.find(r=>r[0]===view)?.[2]||'怪物資料庫'}
async function render({search=false}={}){const token=++generation;view=location.hash.slice(1).split('?')[0]||'monsters';if(!routes.some(r=>r[0]===view))view='monsters';updateHeader();if(!search)$('#app').innerHTML='<div class="loading">正在載入資料…</div>';try{let html;if(view==='home')html=await home();else if(view==='training')html=await trainingPage();else if(['monsters','items','maps','skills','quests'].includes(view))html=await database();else if(view==='plan')html=await plan();else if(view==='favorites')html=await favorites();else if(view==='exp')html=experiencePage({profile:save.profile,records:save.records,mode:expMode,heading,table,e,fmt});else if(view==='guides')html=await guides();else if(view==='tools')html=await tools();else if(view==='audit')html=await auditPage();else html=await library();if(token!==generation)return;$('#app').innerHTML=html;bindView();return true}catch(err){if(token===generation)$('#app').innerHTML=`<div class="empty">${e(err.message)}<br><button class="secondary" id="retry">重新載入</button></div>`}}
async function home(){const p=save.profile,counts=await data('counts'),skills=await data('attack-skills'),quests=await data('quests'),attack=skills.find(s=>Number(s.id)===p.attackSkill);return heading('今天，也往下一級前進。','依目前角色的職業與主要攻擊技能，自動整理練功方向。')+await trainingSummary()+`<section class="hero"><div><h2>Lv.${p.level} ${e(jobName(p))}，今天去哪裡練？</h2><p>STR ${p.str} · DEX ${p.dex} · INT ${p.int} · LUK ${p.luk}<br>主要攻擊：${e(attack?.name||'普通攻擊')} Lv.${p.attackLevel}。推薦會使用目前角色的職業與技能，不套用其他職業的治癒條件。</p><a class="primary" href="#training">直接看我的練功推薦 →</a></div></section><div class="stats-grid">${[['怪物圖鑑',counts.monsters],['道具資料',counts.items],['任務手札',counts.quests],['地圖名冊',counts.maps]].map(([n,c])=>`<div class="stat"><small>${n}</small><strong>${fmt(c)}</strong><small>V002範圍核對資料</small></div>`).join('')}</div><div class="row-layout"><section><div class="section-head"><h2>符合目前等級／職業的任務</h2><a href="#quests">任務手札 →</a></div><div class="panel">${quests.filter(q=>eligible(q,p)&&!save.completed.includes(q.id)).sort((a,b)=>(b.minLevel||0)-(a.minLevel||0)).slice(0,5).map(q=>`<div class="list-row"><div>${link('quests',q.id,q.name)}<br><small>Lv.${q.minLevel||1}起 · ${e(q.startNpc?.locationText||'地點待核對')}</small></div>${tag(fmt(q.completeRewards?.exp)+' EXP')}</div>`).join('')||'<p>目前沒有符合條件的已核對任務。</p>'}</div></section><section><div class="section-head"><h2>我的攻擊技能</h2><button class="inline-link" id="edit-profile">編輯配置 ↗</button></div><div class="panel"><h3>${e(attack?.name||'普通攻擊')} Lv.${p.attackLevel}</h3><p>${e(jobName(p))} · ${attackMode(p)==='heal'?'使用治癒攻擊不死系':'依這個職業與攻擊技能挑選候選怪物'}</p><p class="note">面板物攻：${p.attack||'尚未填寫'} · 魔攻：${p.magic||'尚未填寫'}。未取得完整面板與實測傷害前，不推算幾下必殺或保證時薪。</p></div></section></div>`}

async function database(){
 const rows=await data(view),names={monsters:['怪物資料庫','依等級、地區與屬性篩選，點怪物查看掉落物與出沒地圖。'],items:['道具資料庫','裝備、消耗品、素材、取得來源與製作配方。'],quests:['任務資料庫','勾選表示已完成，取消勾選表示未完成；進度自動保存在目前瀏覽器。'],maps:['地圖資料庫','各地區怪物、NPC、傳送點與地圖配置。'],skills:['技能資料庫','全職業技能，依職業分類查看逐級數值。']};
 let matches=rows.filter(r=>`${r.name} ${r.id} ${r.parent||''} ${r.category||''} ${r.subcategory||''} ${r.jobName||''} ${r.regionName||''} ${r.searchTerms||''}`.toLowerCase().includes(query.toLowerCase()));
 if(view==='quests'&&questStatus!=='all')matches=matches.filter(r=>save.completed.includes(String(r.id))===(questStatus==='completed'));
 const rowLevel=r=>view==='quests'?r.minLevel:view==='items'?r.equipStats?.reqLevel:r.level;
 if(filter)matches=matches.filter(r=>view==='items'?r.category===filter:view==='maps'?r.regionName===filter:view==='skills'?r.jobGroup===filter:true);
 if(minLevel!=='')matches=matches.filter(r=>rowLevel(r)!=null&&rowLevel(r)>=Number(minLevel));if(maxLevel!=='')matches=matches.filter(r=>rowLevel(r)!=null&&rowLevel(r)<=Number(maxLevel));
 if(onlyRole&&view==='quests')matches=matches.filter(r=>eligible(r,save.profile));if(healOnly&&view==='monsters')matches=matches.filter(r=>r.stats?.undead);if(bossOnly&&view==='monsters')matches=matches.filter(r=>r.stats?.boss);if(region&&view==='monsters')matches=matches.filter(r=>r.continents?.includes(region));if(weakness&&view==='monsters')matches=matches.filter(r=>r.elemental?.values?.[weakness]==='weak');
 if(sortOrder==='exp')matches.sort((a,b)=>(b.stats?.exp??b.completeRewards?.exp??-1)-(a.stats?.exp??a.completeRewards?.exp??-1));else if(sortOrder==='hp')matches.sort((a,b)=>(a.stats?.maxHP??Infinity)-(b.stats?.maxHP??Infinity));else if(sortOrder==='name')matches.sort((a,b)=>a.name.localeCompare(b.name,'zh-Hant'));else if(['monsters','items','quests'].includes(view))matches.sort((a,b)=>(rowLevel(a)??Infinity)-(rowLevel(b)??Infinity));
 const key={items:'category',maps:'regionName',skills:'jobGroup'}[view],categories=key?[...new Set(rows.map(r=>r[key]).filter(Boolean))]:[],pages=Math.max(1,Math.ceil(matches.length/36));page=Math.min(page,pages);const slice=matches.slice((page-1)*36,page*36);
 const photo=(kind,r)=>`<div class="db-identity">${sprite(r.image)}<div>${link(kind,r.id,r.name)}<small>ID ${e(r.id)}</small></div></div>`;
 let headers,records;
 if(view==='monsters'){headers=['怪物','等級','HP','EXP','魔防','屬性弱點','掉落物／所在地圖','收藏'];records=slice.map(m=>[photo('monsters',m),m.level??'—',fmt(m.stats?.maxHP),fmt(m.stats?.exp),fmt(m.stats?.MDDamage),`${m.stats?.undead?tag('治癒'):''}${Object.entries(m.elemental?.values||{}).filter(([,v])=>v==='weak').map(([k])=>tag({fire:'火',ice:'冰',lightning:'雷',poison:'毒',holy:'聖'}[k]||k)).join('')||'<span class="muted">—</span>'}`,`<div class="db-preview">${e((m.dropNames||[]).slice(0,4).join('、')||'掉落未收錄')}<small>${e((m.mapNames||m.continents||[]).slice(0,3).join('、'))}</small>${link('monsters',m.id,`查看 ${m.dropCount??0} 種掉落／地圖`)}</div>`,`<button class="favorite" data-favorite="monsters:${m.id}" aria-label="收藏${e(m.name)}">${favorite('monsters',m.id)?'★':'☆'}</button>`]);}
 if(view==='items'){headers=['道具','分類','需求等級','能力／魔攻','取得來源','收藏'];records=slice.map(r=>[photo('items',r),e(r.subcategory||r.category),fmt(r.equipStats?.reqLevel??0),e(Object.entries(r.equipStats||{}).filter(([k,v])=>['incINT','incLUK','incMAD','incPAD','incSTR','incDEX'].includes(k)&&v).map(([k,v])=>({incINT:'INT',incLUK:'LUK',incMAD:'魔攻',incPAD:'物攻',incSTR:'STR',incDEX:'DEX'}[k])+' +'+v).join(' · ')||'—'),Object.entries(r.sourceCounts||{}).filter(([,v])=>v).map(([k,v])=>`${e({monsterDrops:'怪物',questRewards:'任務獎勵',questRequirements:'任務需求',shops:'商店',crafts:'製作',craftRequirements:'製作材料',boxChoices:'箱子選項',boxSources:'箱子',gachaSources:'轉蛋',exchangeSources:'兌換'}[k]||k)} ${v}`).join(' · ')||'來源未收錄',`<button class="favorite" data-favorite="items:${r.id}" aria-label="收藏${e(r.name)}">${favorite('items',r.id)?'★':'☆'}</button>`]);}
 if(view==='quests'){headers=['任務／前置系列','等級','地點','完成經驗','我的進度'];records=slice.map(q=>[`${link('quests',q.id,q.name)}<br><small class="muted">${e(q.parent)}</small>`,`${q.minLevel??'—'}～${q.maxLevel??'無上限'}`,e(q.startNpc?.locationText||'未知'),fmt(q.completeRewards?.exp),`<button class="secondary" data-plan="${q.id}">${save.selected.includes(q.id)?'已加入 ✓':'加入規劃 ＋'}</button> ${questCompletion(q.id,q.name)}`]);}
 if(view==='maps'){headers=['地圖名稱','地區','生怪點','NPC','傳送點','收藏'];records=slice.map(r=>[`${link('maps',r.id,r.name)}<br><small class="muted">${e(r.street)} · ${r.id}</small>`,e(r.regionName||'未分類'),fmt(r.monsterSpawnCount),fmt(r.npcSpawnCount),fmt(r.portalCount),`<button class="favorite" data-favorite="maps:${r.id}" aria-label="收藏${e(r.name)}">${favorite('maps',r.id)?'★':'☆'}</button>`]);}
 if(view==='skills'){headers=['技能','職業','轉職階段','等級上限','收藏'];records=slice.map(r=>[photo('skills',r),e(r.jobName),e(r.advancement),r.maxLevel,`<button class="favorite" data-favorite="skills:${r.id}" aria-label="收藏${e(r.name)}">${favorite('skills',r.id)?'★':'☆'}</button>`]);}
 const recommendation=view==='monsters'?await trainingSummary():'';
 return heading(...names[view])+recommendation+`<div class="database-tabs">${[['monsters','怪物'],['items','道具'],['quests','任務'],['maps','地圖'],['skills','技能']].map(([id,n])=>`<a href="#${id}" class="${view===id?'active':''}">${n}</a>`).join('')}</div><section class="db-filter-panel"><div class="toolbar"><div class="search"><input id="db-search" type="search" aria-label="搜尋資料" placeholder="${view==='monsters'?'搜尋怪物、掉落物、地圖名稱或 ID':'輸入名稱、分類或 ID'}" value="${e(query)}"></div>${categories.length?`<select id="category-filter" aria-label="分類"><option value="">全部分類</option>${categories.map(c=>`<option ${filter===c?'selected':''}>${e(c)}</option>`).join('')}</select>`:''}<button class="secondary" id="clear-search">清除條件</button></div><div class="advanced-filters">${['monsters','quests','items'].includes(view)?`<label>最低等級<input id="min-level" aria-label="最低等級" type="number" min="0" max="200" value="${e(minLevel)}" placeholder="不限"></label><label>最高等級<input id="max-level" aria-label="最高等級" type="number" min="0" max="200" value="${e(maxLevel)}" placeholder="不限"></label>`:''}${view==='monsters'?`<label>所在地區<select id="region-filter"><option value="">全部地區</option>${[...new Set(rows.flatMap(r=>r.continents||[]))].sort().map(r=>`<option ${region===r?'selected':''}>${e(r)}</option>`).join('')}</select></label><label>屬性弱點<select id="weakness-filter"><option value="">全部屬性</option>${Object.entries({fire:'火',ice:'冰',lightning:'雷',poison:'毒',holy:'聖'}).map(([k,n])=>`<option value="${k}" ${weakness===k?'selected':''}>${n}</option>`).join('')}</select></label><label class="check"><input type="checkbox" id="heal-filter" ${healOnly?'checked':''}>治癒有效（不死系）</label><label class="check"><input type="checkbox" id="boss-filter" ${bossOnly?'checked':''}>只顯示BOSS</label><button class="secondary" id="cleric-preset">套用${save.profile.level}級${e(jobName(save.profile))}候選</button>`:''}${view==='quests'?`<label>任務進度<select id="quest-status" aria-label="任務進度">${[['all','全部任務'],['incomplete','未完成'],['completed','已完成']].map(([id,n])=>`<option value="${id}" ${questStatus===id?'selected':''}>${n}</option>`).join('')}</select></label><label class="check"><input type="checkbox" id="role-filter" ${onlyRole?'checked':''}>符合${save.profile.level}級${e(jobName(save.profile))}等級／職業</label>`:''}</div></section><div class="result-meta"><span>顯示 ${matches.length?((page-1)*36+1):0}–${Math.min(page*36,matches.length)} / ${fmt(matches.length)} 筆 · 全部 ${fmt(rows.length)} 筆</span><label>排序 <select id="sort-order" aria-label="排序方式">${[['level','等級由低到高'],['name','名稱'],['exp','經驗由高到低'],['hp','血量由低到高']].map(([id,n])=>`<option value="${id}" ${sortOrder===id?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="dense-db">${table(headers,records)}</div><div class="pagination"><button class="secondary" id="prev" ${page===1?'disabled':''}>← 上一頁</button><span>${page} / ${pages}</span><button class="secondary" id="next" ${page===pages?'disabled':''}>下一頁 →</button></div><p class="source-note">資料來源：楓憶MapleMemory結構化快照。已依官方V002範圍篩選；數值與伺服器腳本仍待實測。未確認項目及原因請看「版本審核」。</p>`;
}
async function plan(){const qs=await data('quests'),result=expandPlan(qs,save.selected,save.completed),selected=result.quests;const items=totals(selected,'items'),kills=totals(selected,'monsters');const exp=selected.reduce((s,q)=>s+(q.completeRewards?.exp||0),0);return heading('我的材料清單','選好的任務，自動展開必須完成的前置；完成項目會從需求中扣除。')+`<div class="stats-grid">${[['規劃任務',selected.length],['材料種類',items.length],['需擊殺數',kills.reduce((s,r)=>s+r.count,0)],['完成經驗',exp]].map(([t,n])=>`<div class="stat"><small>${t}</small><strong>${fmt(n)}</strong></div>`).join('')}</div>${result.missing.length?`<div class="notice">缺少前置 ${e(result.missing.join('、'))}，需求可能不完整。</div>`:''}<div class="panel"><div class="section-head"><h2>已選任務</h2><a href="#quests">新增任務 ＋</a></div>${save.selected.length?save.selected.map(id=>{const q=qs.find(q=>q.id===id);return `<div class="list-row"><span>${q?link('quests',id,q.name):e(id)+'（暫未通過版本審核，不列入需求）'}</span><div>${questCompletion(id,q?.name||id)} <button class="secondary" data-plan="${id}">移除</button></div></div>`}).join(''):'<div class="empty">先到任務手札，把想解的任務加入規劃。</div>'}</div><div class="section-head"><h2>需要收集的材料</h2><button id="export-materials" class="secondary">下載 CSV ↓</button></div>${table(['材料','數量','查詢'],items.map(r=>[e(r.name),fmt(r.count),link('items',r.id,'查看掉落／商店／製作 ↗')]))}<div class="section-head"><h2>需要擊殺的怪物</h2></div>${table(['怪物','擊殺數','出沒地圖'],kills.map(r=>[e(r.name),fmt(r.count),link('monsters',r.id,'查看怪物 ↗')]))}<div class="section-head"><h2>完整前置與地點</h2></div>${table(['任務','接取地點','交付地點'],selected.map(q=>[link('quests',q.id,q.name),e(q.startNpc?.locationText||'未知'),e(q.endNpc?.locationText||'未知')]))}<div class="notice">按材料ID加總繳交需求，不重複計算獎勵區的「收回材料」。未扣背包、任務發放材料，未合併可共計擊殺。互斥、職業與名聲等條件仍需在遊戲內確認；這不是全任務最短路線。</div>`}
