function facts(value,depth=0){if(value===null||value===undefined)return '<span class="muted">未知／未列</span>';if(typeof value!=='object')return e(typeof value==='boolean'?(value?'是':'否'):value);if(depth>9)return '<span class="muted">完整內容可由下方資料檔下載</span>';if(Array.isArray(value)){if(!value.length)return '<span class="muted">來源未列</span>';if(value.every(x=>typeof x!=='object'))return value.map(e).join('、');return value.map((v,i)=>`<details><summary>${e(v?.name||v?.monsterName||v?.questName||v?.label||((v?.level!=null?'Lv.'+v.level:'第'+(i+1)+'筆')))}</summary>${facts(v,depth+1)}</details>`).join('')}return `<dl>${Object.entries(value).filter(([k])=>!hiddenFields.has(k)).map(([k,v])=>`<dt class="muted">${e(fieldLabels[k]||k)}</dt><dd>${facts(v,depth+1)}</dd>`).join('')}</dl>`}
