if(activeTool==='scroll'){const d=await data('scroll-simulator');content=`<h2>卷軸的成功與破壞風險</h2><form id="scroll-form" class="tool-form"><label class="field">卷軸<select name="scroll">${d.scrolls.map((s,i)=>`<option value="${i}">${e(s.name)}</option>`).join('')}</select></label><label class="field">獨立使用次數<input name="attempts" type="number" min="1" max="10000" value="100" required></label><button class="primary">模擬</button></form><div id="scroll-result"></div><div class="notice">每次視為對一件新的相容裝備使用，不模擬同一件裝備連續衝卷。破壞率按失敗後條件機率計算；非實際遊戲結果。</div>`;}
if(activeTool==='gacha'){const d=await data('gacha-simulator');content=`<h2>公開獎池與抽取情境</h2><form id="gacha-form" class="tool-form"><label class="field">獎池<select id="gacha-pool" name="pool">${d.pools.map((p,i)=>`<option value="${i}">${e(p.name)}</option>`).join('')}</select></label><label class="field">次數<input name="attempts" type="number" min="1" max="10000" value="10" required></label><button class="primary">模擬（不消費）</button></form><div id="gacha-result"></div><div class="notice">獎池可能含多種來源分組，僅在所選池的第一個明確分組內按權重模擬；不代表目前在售或實際保證收益。完整各分組、來源與期間見資料中心。</div>`;}
if(activeTool==='boss'){content=`<h2>我的 BOSS 重生提醒</h2><form id="boss-form" class="tool-form"><label class="field">BOSS與頻道<input name="name" required placeholder="紅寶王 · CH1"></label><label class="field">自行設定等待分鐘<input name="minutes" type="number" min="1" max="10080" value="60" required></label><button class="primary">從現在開始計時</button></form><div id="timer-list">${timerHTML()}</div><div class="notice">時間由你自行輸入，並非宣稱官方重生週期。關閉頁面仍保存截止時間；不提供離線推播通知。</div>`;}
