async function favorites(){let cards=[];for(const kind of ['monsters','items','maps','skills']){const ids=new Set(save.favorites.filter(x=>x.startsWith(kind+':')).map(x=>x.split(':')[1]));if(ids.size){const rows=await data(kind);cards.push(...rows.filter(r=>ids.has(String(r.id))).map(r=>card(kind,r)))}}return heading('我的收藏','把常查的怪物、道具、地圖與技能留在手邊。')+`<div class="grid">${cards.join('')||'<div class="empty">點選圖鑑卡片右上角的星號，就能加入收藏。</div>'}</div>`}

function bindDatabaseFilters(){for(const [id,set]of[['min-level',v=>minLevel=v],['max-level',v=>maxLevel=v],['region-filter',v=>region=v],['weakness-filter',v=>weakness=v],['sort-order',v=>sortOrder=v]]){const el=$('#'+id);if(el)el.onchange=()=>{set(el.value);page=1;render()}}if($('#boss-filter'))$('#boss-filter').onchange=event=>{bossOnly=event.target.checked;page=1;render()};if($('#cleric-preset'))$('#cleric-preset').onclick=()=>{minLevel=String(Math.max(1,save.profile.level-15));maxLevel=String(save.profile.level+1);healOnly=attackMode(save.profile)==='heal';bossOnly=false;query='';filter='';region='';weakness='';page=1;render()};bindSearchInput('#guide-search',value=>{guideQuery=value});if($('#guide-category'))$('#guide-category').onchange=event=>{guideCategory=event.target.value;render()}}
async function guides(){const d=await data('guides'),rows=d.guides.filter(g=>(!guideCategory||g.category===guideCategory)&&(g.title+' '+g.source).toLowerCase().includes(guideQuery.toLowerCase()));return heading('攻略指南','整合波波攻略島與楓錄的經典版入口，按主題查找並連回原文。')+`<div class="toolbar"><div class="search"><input id="guide-search" aria-label="搜尋攻略" placeholder="搜尋練功、任務、職業、材料…" value="${e(guideQuery)}"></div><select id="guide-category" aria-label="攻略分類"><option value="">全部主題</option>${[...new Set(d.guides.map(g=>g.category))].map(c=>`<option ${c===guideCategory?'selected':''}>${e(c)}</option>`).join('')}</select></div><p class="result-meta">${rows.length} 個攻略入口</p>${table(['主題','攻略','來源','版本狀態'],rows.map(g=>[tag(g.category),`<a href="${e(g.url)}" target="_blank" rel="noopener">${e(g.title)} ↗</a>`,e(g.source),e(g.status)]))}<div class="notice">楓錄首頁已公告停止更新。攻略原文的本服實測、舊版參考與改版預覽分開看待；此頁提供分類與連結，沒有把站長文章全文搬成自己的攻略。</div>`}

async function auditPage(){const d=await data('version-audit'),labels={maps:'地圖',monsters:'怪物',quests:'任務',items:'道具'},statuses={scoped:'範圍核對通過・數值待實測',pending:'待確認・暫不發布',excluded:'超出當期範圍'};const rows=d.records.filter(r=>(auditKind==='all'||r.kind===auditKind)&&(auditStatus==='all'||r.status===auditStatus)&&(r.name+' '+r.id+' '+r.reason).toLowerCase().includes(auditQuery.toLowerCase()));const pages=Math.max(1,Math.ceil(rows.length/36));auditPageNumber=Math.min(auditPageNumber,pages);return heading('版本審核','台版 V002｜2026/10/15 天空之城・冰原雪域｜120級・三轉')+`<div class="notice">${d.limitations.map(e).join('<br>')}</div><h2>官方核對依據</h2>${table(['公告','查閱日期'],d.official.sources.map(s=>[`<a href="${e(s.url)}" target="_blank" rel="noopener">${e(s.title)} ↗</a>`,e(s.checkedAt)]))}<h2>全資料範圍檢查</h2>${table(['類別','原始筆數','範圍符合','待確認','超出範圍'],Object.entries(d.summary).map(([k,s])=>[labels[k],fmt(s.total),fmt(s.scoped||0),fmt(s.pending||0),fmt(s.excluded||0)]))}<p class="muted">這是逐筆來源與範圍檢查，不是逐筆遊戲實測認證；未確認資料不進入圖鑑、材料規劃或推薦。</p><h2>查詢每筆審核結果</h2><div class="toolbar"><input id="audit-search" type="search" aria-label="搜尋審核資料" placeholder="輸入名稱、ID或原因" value="${e(auditQuery)}"><select id="audit-kind" aria-label="審核類別"><option value="all">全部類別</option>${Object.entries(labels).map(([k,n])=>`<option value="${k}" ${auditKind===k?'selected':''}>${n}</option>`).join('')}</select><select id="audit-status" aria-label="審核狀態"><option value="all">全部狀態</option>${Object.entries(statuses).map(([k,n])=>`<option value="${k}" ${auditStatus===k?'selected':''}>${n}</option>`).join('')}</select></div><p class="result-meta">${fmt(rows.length)} 筆</p>${table(['類別','名稱／ID','狀態','依據或暫緩原因'],rows.slice((auditPageNumber-1)*36,auditPageNumber*36).map(r=>[labels[r.kind],e(r.name)+'<br><small>'+e(r.id)+'</small>',e(statuses[r.status]),e(r.reason)]))}<div class="pagination"><button id="audit-prev" class="secondary" ${auditPageNumber===1?'disabled':''}>← 上一頁</button><span>${auditPageNumber} / ${pages}</span><button id="audit-next" class="secondary" ${auditPageNumber===pages?'disabled':''}>下一頁 →</button></div><h2>已移除或暫緩的來源關係</h2><h2>台版資料交叉核對</h2><p>${fmt(d.crossChecks.matched)} 個非空數值一致，${fmt(d.crossChecks.missing)} 個缺值比較維持未知，衝突 ${d.crossChecks.conflicts.length} 個。${e(d.crossChecks.note)}</p>${table(['項目','筆數'],Object.entries(d.removedRelations).map(([k,v])=>[e(k),fmt(v)]))}`}

async function currentAttack(){return (await data('attack-skills')).find(s=>Number(s.id)===save.profile.attackSkill)||{id:0,name:'普通攻擊',levels:[]}}
async function trainingSummary(){const p=save.profile,picks=recommendTraining(await data('training'),p),first=picks[0],attack=await currentAttack();if(!first)return `<div class="notice">目前配置在已核對資料中沒有合適的保守練功候選。<a href="#training">查看練功推薦</a></div>`;return `<section class="training-summary"><div><small>依你的 ${p.level} 級${e(jobName(p))}與${e(attack.name)} Lv.${p.attackLevel}自動推薦</small><h2>現在先去：${e(first.map.name)}</h2><p>主要打 ${e(first.monster.name)}（Lv.${first.monster.level} · HP ${fmt(first.monster.hp)}）。${attackMode(p)==='heal'?'以群體治癒挑不死系，依技能階段先比較清怪壓力。':`使用${e(attack.name)}，候選不限不死系。`}</p></div><a class="primary" href="#training">查看推薦地圖與替代選擇 →</a></section>`}
async function trainingPage(){const p=save.profile,mode=attackMode(p),attack=await currentAttack(),skillValues=attack.levels?.find(r=>r.level===p.attackLevel)?.values||{},picks=recommendTraining(await data('training'),p);return heading('練功推薦',`依你的 Lv.${p.level} ${jobName(p)}、${attack.name} Lv.${p.attackLevel} 自動挑選。`)+`<div class="panel"><strong>使用技能：${e(attack.name)} Lv.${p.attackLevel}</strong><p class="muted">${skillValues.damage!=null?'技能傷害係數 '+skillValues.damage+'% · ':''}${skillValues.mad!=null?'技能魔攻 '+skillValues.mad+' · ':''}${skillValues.mpCon!=null?'每次消耗 '+skillValues.mpCon+' MP · ':''}${skillValues.hp!=null&&mode==='heal'?'恢復力 '+skillValues.hp+'%（不是對怪傷害係數） · ':''}實際傷害仍受武器、面板與怪物防禦影響。</p></div><div class="notice">直接依目前職業、攻擊技能與技能等級給你出發順序，不需要先選怪物或地圖。只使用已通過V002範圍核對的地圖與怪物；這是保守候選，尚無你的武器完整面板與實測傷害，不能保證最高時薪。</div>${[410,411].includes(p.jobId)&&p.int>p.luk*2?'<div class="notice">目前INT較高、LUK較低，可能仍是另一個角色的能力值；若這是新刺客，請更新這隻角色的配置。</div>':''}<div class="section-head"><h2>現在可以去哪裡練</h2><button class="secondary" id="edit-profile">更新我的配置</button></div><div class="training-list">${picks.map((pick,i)=>{const {map,monster,others}=pick;const rank=i===0?'首選：現在先去':i===1?'替代：想換點時去':'第三選擇';const reason=mode==='heal'?`以群體治癒 Lv.${p.attackLevel}攻擊${e(monster.name)}這類不死系；${p.attackLevel<16?'技能還低，先挑血量較低的候選。':'優先比較接近角色等級的候選。'}`:mode==='ranged'?`以${e(attack.name)} Lv.${p.attackLevel}進行遠距攻擊，候選不限定不死系；地圖排序較重視目標分布與同圖風險。`:mode==='magic'?`以${e(attack.name)} Lv.${p.attackLevel}作為主要攻擊，不套用治癒的不死系限制；先比較這隻怪的清怪速度與補給。`:`以${e(attack.name)} Lv.${p.attackLevel}攻擊，優先比較移動負擔較低、混怪風險較少的地圖。`;return `<article class="panel training-card" data-training-map="${e(map.id)}"><div class="section-head"><span class="tag ${i===0?'gold':''}">${rank}</span><small>${e(map.regionName)}</small></div><h2>${e(map.name)}</h2><h3>主要打：${e(monster.name)}</h3><div class="card-stats"><div>怪物等級<strong>Lv.${monster.level}</strong></div><div>HP<strong>${fmt(monster.hp)}</strong></div><div>單隻EXP<strong>${fmt(monster.exp)}</strong></div></div><p>${reason}</p><p class="muted">地圖資料列出 ${monster.count} 個目標生怪點，占已知生怪點約 ${Math.round(pick.share*100)}%。排序也參考地圖寬高及攻擊方式；這不是實際同時怪量或每分鐘重生量。</p>${others.length?`<div class="notice">同圖還有：${others.map(m=>e(m.name)+' Lv.'+m.level).join('、')}。${mode==='heal'&&others.some(m=>!m.undead)?'非不死系需要用其他攻擊技能處理。':''}</div>`:''}<div class="form-actions">${link('maps',map.id,'查看地圖與出入口')}${link('monsters',monster.id,'查看怪物與掉落')}</div></article>`}).join('')||'<div class="empty">目前已核對資料不足以對這個配置給出保守候選；暫不拿未確認地圖湊推薦。</div>'}</div><div class="notice">${mode==='heal'?`魔力吸收${p.absorb}不代表無限MP；目前瞬移${p.teleport}，先以走路、爬繩配合少量瞬移。`:mode==='ranged'?'遠距攻擊仍需要注意貼身、站位、補給與消耗品。':'先用目前技能測試清怪與補給，不套用其他職業的打法。'}先照首選出發即可；若怪量被搶或清怪不順，再換第二張。更換角色、職業或攻擊技能後，推薦會自動重算。</div>`}
